CREATE OR REPLACE VIEW `view_schichtleiter_anwesenheit` AS
select `p`.`oe` AS `oe`,`p`.`name` AS `name`,`b`.`Schicht` AS `schicht`,max(case when `b`.`Datum` = curdate() then `b`.`anwesenheit` end) AS `heute`,max(case when `b`.`Datum` = curdate() + interval 1 day then `b`.`anwesenheit` end) AS `morgen` from (`tbl_ueb_fz_buchungen` `b` left join `tbl_ueb_personalakte_scd` `p` on(`b`.`PersNr` = `p`.`persnr` and `b`.`Datum` between `p`.`gueltig_von` and `p`.`gueltig_bis`)) where `p`.`taetigkeit` in ('Schichtleiter','Betriebsleitung','Leitstand') and `b`.`Datum` between curdate() and curdate() + interval 1 day group by `p`.`oe`,`p`.`name`,`b`.`Schicht` order by `p`.`oe`,`b`.`Schicht`;
